from mk import *
import math
G = 6.67e-11; Mm = 7.35e22; Rm = 1.74e6; T = 27.3 * 86400
r = (G * Mm * T ** 2 / (4 * math.pi ** 2)) ** (1 / 3)
T2 = 2 * math.pi * math.sqrt(3e6 ** 3 / (G * Mm)) / 3600
gm = G * Mm / Rm ** 2

def fig():
    g = Fig(560, 230, "כדור הארץ, הירח במסלולו סביב כדור הארץ, ולוויין במסלול מעגלי סביב הירח")
    ex, ey, mx, my = 120, 115, 400, 115
    g.circle(ex, ey, 46, fill="var(--d-fill)", stroke="var(--d-line)"); g.heb(ex, ey + 6, "כדור הארץ")
    g.path(f"M {ex + 263} {ey - 96} A 280 280 0 0 1 {ex + 263} {ey + 96}", width=1.2, dash="6 5")
    g.circle(mx, my, 22, fill="var(--d-fill)", stroke="var(--d-line)"); g.heb(mx, my + 5, "ירח")
    g.circle(mx, my, 64, fill="none", stroke="var(--d-line)", width=1.2, dash="4 4")
    g.ball(mx + 45, my - 45, r=6); g.heb(mx + 86, my - 56, "לוויין")
    return g

E(id="bagrut-2006-q5", year=2006, label="2006 שאלה 5", topic="gravitation", sub="grav-orbits", diff=3, fig=fig,
  stem=r"הירח נע סביב כדור הארץ, וכל הזמן מפנה אליו אותו הצד. הירח משלים סיבוב מעגלי שלם סביב כדור הארץ במשך $27.3$ יממות ארציות. משני נתונים אלה נובע כי הירח מסתובב גם סביב צירו, וזמן המחזור שלו הוא $27.3$ יממות ארציות. מהנדס עוסק בתכנון תקשורת בין מושבות שיוקמו בעתיד על פני הירח. בדעתו להשתמש בלוויין תקשורת שינוע במסלול מעגלי סביב הירח, כך שזמן המחזור שלו יהיה $27.3$ יממות ארציות, והוא יימצא כל העת מעל נקודה קבועה על פני הירח. נתוני הירח: מסה $7.35 \times 10^{22}\,\text{kg}$, רדיוס $1.74 \times 10^6\,\text{m}$.",
  parts=[
    P("א", r"חשב את רדיוס המסלול המעגלי של לוויין כזה, בהנחה כי רק הירח משפיע על תנועת הלוויין.", num(r / 1000, "km", tol=2), ["principle", "algebra", "units"], [
        S(r"כבידת הירח היא הכוח הצנטריפטלי", r"רק הירח משפיע", r"\frac{GM_m m}{r^2} = m\frac{4\pi^2}{T^2}r"),
        S(r"מבודדים את $r$", r"$T = 27.3 \cdot 86400 \approx 2.36 \times 10^6\,\text{s}$", r"r = \sqrt[3]{\frac{GM_m T^2}{4\pi^2}},\quad GM_m T^2 = 6.67 \times 10^{-11} \cdot 7.35 \times 10^{22} \cdot (2.36 \times 10^6)^2 \approx 2.73 \times 10^{25},\quad r \approx 8.84 \times 10^7\,\text{m}"),
    ], r"$r \approx 88{,}400\,\text{km}$", key=r"r=88,400 km"),
    P("ב", r"המהנדס חישב ומצא שבגלל השפעת כדור הארץ, אי-אפשר למקם את הלוויין במסלול שאת רדיוסו מצאת בסעיף א. הרדיוס המקסימלי של מסלול לוויין סביב הירח שבו אפשר להזניח את השפעת כדור הארץ הוא כ-$3{,}000\,\text{km}$. חשב את זמן המחזור (בשעות) של לוויין שנע סביב הירח במסלול מעגלי שרדיוסו $3{,}000\,\text{km}$.", num(T2, "h", tol=1), ["principle", "algebra", "units"], [
        S(r"אותו קשר, הפעם מבודדים את $T$", r"$r = 3 \times 10^6\,\text{m}$", r"T = 2\pi\sqrt{\frac{r^3}{GM_m}} = 2\pi\sqrt{\frac{(3 \times 10^6)^3}{6.67 \times 10^{-11} \cdot 7.35 \times 10^{22}}} \approx 1.47 \times 10^4\,\text{s}"),
        S(r"לשעות", r"מחלקים ב-3600", r"T \approx 4.1\,\text{h}"),
    ], r"$T \approx 4.1\,\text{h}$", key=r"4.096 h"),
    P("ג", r"חשב את תאוצת הנפילה החופשית על פני הירח.", num(gm, "m/s^2", tol=1), ["principle", "algebra"], [
        S(r"כוח הכבידה על פני הירח", r"$mg_m = GM_m m/R_m^2$", r"g_m = \frac{GM_m}{R_m^2} = \frac{6.67 \times 10^{-11} \cdot 7.35 \times 10^{22}}{(1.74 \times 10^6)^2} \approx 1.62\,\text{m/s}^2"),
    ], r"$\approx 1.62\,\text{m/s}^2$", key=r"gM=1.62 m/s²"),
    P("ד", r"ציין תרומה אחת לידע המדעי על אודות מערכת השמש של אחד מהאישים האלה: ניקולס קופרניקוס, גלילאו גליליי, טיכו ברהה.", OPEN, ["understanding"], [
        X(r"קופרניקוס: הציע שהשמש במרכז וכוכבי הלכת (וכדור הארץ) סובבים סביבה. גלילאו: גילה בטלסקופ את ארבעת הירחים הגדולים של צדק ואת המופעים של נוגה. טיכו ברהה: מדידות מדויקות של מקומות כוכבי הלכת, שעליהן ביסס קפלר את חוקיו."),
    ], r"תשובה פתוחה, למשל: קופרניקוס הציע מודל שבו השמש במרכז"),
  ],
  concepts=["לוויין סינכרוני", "החוק השלישי של קפלר", "תאוצת הכובד על הירח"],
  summary=r"לוויין שנשאר מעל אותה נקודה על הירח: רדיוס המסלול, ומדוע בפועל צריך מסלול קרוב יותר (השפעת כדור הארץ).")
